recs.append(R(6494648,"ہلکے نمکین پستے","50 ہلکے نمکین پستوں کی غذائی معلومات","1","50 پستے",["50 سالم ہلکے نمکین پستے"],[]))
recs.append(R(6494663,"بھنی ہوئی لال شملہ مرچ کا کولی","کولی محض ایک گاڑھی پیوری یا ساس ہوتی ہے۔ یہ آپ کی ڈشز کے لیے ایک خوبصورت اور مزیدار آخری لمس ہے۔ (یہاں Rosemary Balsamic Onions اور Pesto کے ساتھ دکھایا گیا ہے۔)","8","1/4 کپ",["4 درمیانی لال شملہ مرچیں"],
["پوری مرچوں کو براہ راست گرِل یا گیس کے چولھے پر، یا اپنے بروئلر کے نیچے رکھیں۔ باہر سے مکمل طور پر کالی ہونے تک روسٹ کریں۔ ایک پیالے میں رکھ کر پلاسٹک ریپ سے کم از کم 15 منٹ تک مضبوطی سے ڈھانپ دیں۔ ٹھنڈا ہونے کے بعد آپ کالی ہوئی کھال اتار سکتے ہیں۔","روسٹ کی ہوئی مرچ کو فوڈ پروسیسر میں ڈالیں اور باریک ہونے تک پیوری بنا لیں۔"]))
recs.append(R(6495824,"اسکیلپ کباب","اسکیلپ تیار کرنے کا یہ ایک بالکل مختلف طریقہ ہے۔ زیادہ تر تراکیب میں انہیں پین میں سیئر کرنے کو کہا جاتا ہے، لیکن کیوں نہ کچھ نیا آزمایا جائے۔ میں اسکیلپ پر کرکرے پانکو کے ٹکڑوں کی تہہ لگاتا/لگاتی ہوں جن میں پارمیزان اور لہسن کا ذائقہ ہوتا ہے، اور انہیں سیخوں میں پرو کر کباب بناتا/بناتی ہوں۔ بروئلر کے نیچے باہر سے کرکرا پن آ جاتا ہے اور اسکیلپ کا اندرونی حصہ ریشمی رہتا ہے۔","4","3 اونس",
["8 عدد لکڑی کی سیخیں","1/2 کپ پانکو بریڈ کرمبز","2 کھانے کے چمچ پارمیزان پنیر (کدوکش کیا ہوا)","3 جوے لہسن (بہت باریک کٹا ہوا، تقریباً پیسٹ کی طرح)","1 چائے کا چمچ اطالوی مسالا","12 اونس بڑے سمندری اسکیلپ (تازہ یا منجمد، پگھلائے ہوئے اور تھپتھپا کر خشک کیے ہوئے)","1 اسپرے، 0.25 گرام زیتون کے تیل کا کوکنگ اسپرے"],
["لکڑی کی سیخوں کو گرم پانی کے برتن میں ڈال دیں۔ انہیں 1–2 گھنٹے کے لیے ایک طرف رکھ دیں۔","بروئلر پین کو ایلومینیم فوائل سے ڈھانپ دیں۔ فوائل پر کوکنگ اسپرے لگائیں۔ اوون کے بروئلر کو تیز پر پہلے سے گرم کریں اور ریک کو حرارت کے ماخذ سے تقریباً 5 انچ کے فاصلے پر رکھیں۔","ڈبل روٹی کے چورے، پارمیزان پنیر، لہسن اور اطالوی مسالے کو ایک پلیٹ میں ملا لیں۔ ہر اسکیلپ کو اس چورے کے مرکب میں لپیٹ لیں۔","لکڑی کی سیخوں کو گرم پانی سے نکال لیں۔ ہر کباب کے لیے دو سیخیں استعمال کرتے ہوئے اسکیلپ کو سیخوں میں پرو دیں تاکہ اسکیلپ سیخ پر سیدھے لیٹے رہیں۔","سیخوں کو تیار کردہ بروئلر پین پر رکھیں۔ ہر سیخ پر زیتون کے تیل کا کوکنگ اسپرے کریں۔ اسکیلپ کو ہر طرف تقریباً 4 منٹ تک بروئل کریں جب تک اندر تک پک نہ جائیں۔"]))
recs.append(R(6496705,"کاؤبوائے بین فرٹرز","اگلی گرمیوں کی بار بی کیو پارٹی میں شیئر کرنے کے لیے یہ اسٹارٹر لے جائیں۔ فرٹرز کو سالسا اور بغیر چکنائی والے سادہ یونانی دہی (کھٹی کریم کا زیادہ صحت مند متبادل) جیسے ڈپس کے ساتھ پیش کریں۔","20","3 فرٹرز",
["1 3/4 کپ میدہ (آل پرپز آٹا)","2 چائے کے چمچ بیکنگ پاؤڈر","1/2 چائے کا چمچ زیرہ","2 چائے کے چمچ نمک","1/2 چائے کا چمچ کالی مرچ","4 انڈوں کی سفیدی (ہلکی پھینٹی ہوئی)","1 کپ سالسا","2 ڈبے کالی پھلیاں (16 اونس، دھوئی ہوئی اور پانی نکالی ہوئی)","1 کھانے کا چمچ سبزیوں کا تیل (ضرورت ہو تو مزید)"],
["ایک بڑے پیالے میں آٹا، بیکنگ پاؤڈر، زیرہ، نمک اور کالی مرچ ملائیں۔ انڈوں کی سفیدی اور سالسا ڈال کر اچھی طرح ملائیں، پھر کالی پھلیاں ہلا کر ملا دیں۔","ایک بڑے فرائنگ پین میں درمیانی تیز آنچ پر 1 کھانے کا چمچ تیل گرم کریں۔ ہر فرٹر کے لیے 1 چائے کا چمچ آمیزہ پین میں ڈالیں، ایک وقت میں کئی فرٹرز پکائیں، لیکن انہیں زیادہ بھیڑ میں نہ رکھیں۔ 1 منٹ پکائیں، پھر فرٹرز کو پلٹیں اور اسپیچولا سے ہلکا سا دبا کر چپٹا کریں؛ مزید 1 سے 2 منٹ پکائیں یا دونوں طرف سے بھورا ہونے تک۔ باقی آمیزے کے ساتھ یہی عمل دہرائیں اور ضرورت کے مطابق مزید تیل ڈالیں۔"]))
recs.append(R(6497012,"بھاپ میں پکی بروکلی","بھاپ میں پکی بروکلی کی غذائی معلومات","1","1 کپ",["1 کپ بروکلی (منجمد)"],
["منجمد بروکلی کے پھولے مائیکرو ویو کے لیے محفوظ پیالے میں رکھیں۔","2–4 کھانے کے چمچ پانی ڈالیں۔","پیالے کو مائیکرو ویو کے لیے محفوظ پلیٹ یا ڈھکن سے ڈھانپ دیں۔","نرم ہونے تک 2–4 منٹ مائیکرو ویو میں زیادہ (high) پاور پر پکائیں۔","احتیاط سے نکالیں، کیونکہ بھاپ گرم ہوگی۔"]))
recs.append(R(6497459,"کلاسک اطالوی مرینارا سالم گندم کے پاستا کے ساتھ","آپ بوتل بند تیار ساسوں کی قیمت کے ایک معمولی حصے میں اپنی مرینارا ساس خود بنا سکتے ہیں۔ یہ ساس لہسن پر بہت زیادہ انحصار کرتی ہے، لیکن اگر آپ چاہیں تو اس تیز ذائقے کو کم کر سکتے ہیں۔ یا تو لہسن کی مقدار کم کریں یا لہسن کو باریک کاٹنے کے بجائے قتلے کر لیں۔ آپ لہسن کو جتنا زیادہ کوٹیں یا باریک کاٹیں گے، آپ کی آخری ڈش اتنی ہی تیز ہوگی۔ لہسن کے بڑے ٹکڑے، ذائقہ دار ہونے کے باوجود، زیادہ ہلکا ذائقہ چھوڑتے ہیں۔ یہ ساس فریز کرنے کے لیے بہترین ہے۔ اسے موٹے زپ والے فریزر بیگ میں ڈال کر 6 ماہ تک محفوظ کریں۔","10","1/2 کپ",
["2 کھانے کے چمچ زیتون کا تیل","5 جوے لہسن (باریک کٹے ہوئے)","1 (28 اونس) ڈبہ بند ٹماٹر (اچھے معیار کے، ترجیحاً اپنے رس میں پیک کیے ہوئے، پانی نکالا ہوا، رس بچا کر رکھیں)","5 پتے تازہ تلسی (کٹے ہوئے، یا آپ انہیں سالم بھی رکھ سکتے ہیں)","10 اونس سالم گندم کا پاستا (پین، شیلز، فوسیلی)","1/4 چائے کا چمچ کوشر نمک","1/4 چائے کا چمچ کالی مرچ (تازہ پسی ہوئی)","1/4 چائے کا چمچ پسی ہوئی لال مرچ کے فلیکس (اختیاری)","2 کھانے کے چمچ پارمیزان یا رومانو پنیر (تازہ کدوکش کیا ہوا)"],
["ایک بڑے ڈھکن والے فرائنگ پین میں زیتون کا تیل اور لہسن ہلکی آنچ پر گرم کریں (گہرا برتن استعمال نہ کریں، کیونکہ آپ چاہتے ہیں کہ پانی جلدی خشک ہو اور ساس گاڑھی ہو جائے)۔ لہسن کو تقریباً 6-7 منٹ تک پکائیں، لیکن بھورا نہ ہونے دیں، کبھی کبھار ہلاتے رہیں۔","اس دوران نتھارے ہوئے ٹماٹر ایک گہرے پیالے میں ڈالیں۔ ٹماٹروں کو ہاتھوں سے موٹا موٹا کچل دیں۔ ٹماٹر اور تلسی فرائنگ پین میں ڈالیں اور 20-25 منٹ تک ہلکی آنچ پر پکائیں جب تک گاڑھا نہ ہو جائے۔ اگر ساس بہت گاڑھی ہو تو ٹماٹر کے ڈبے سے بچایا ہوا کچھ رس ڈال دیں۔","اس دوران 3-5 کوارٹ کے برتن میں ہلکے نمکین پانی (برتن کو 2/3 بھر کر) کو زور کے ابال تک لائیں۔ پاستا ڈالیں اور پہلے منٹ تک ہلاتے رہیں۔ پاستا کو تقریباً 7-8 منٹ تک پکاتے رہیں جب تک ال دانتے نہ ہو جائے۔ پانی نتھار لیں، دھوئیں نہیں۔","اگر استعمال کر رہے ہوں تو نمک، کالی مرچ اور کٹی ہوئی لال مرچ ٹماٹر کی ساس میں ڈالیں۔ پاستا ساس میں ڈالیں، ڈھانپ دیں اور پاستا کو 1-2 منٹ ساس میں پڑا رہنے دیں۔ پاستا کو گرم کیے ہوئے پیالے میں ڈالیں اور اوپر پنیر چھڑکیں۔ (ساس کو فریز بھی کیا جا سکتا ہے۔ ایک کوارٹ کے ڈبے میں فریز کریں اور 3-4 ماہ تک محفوظ رکھیں۔)"]))
recs.append(R(6497482,"بروشیٹا بھرے مشروم","بروشیٹا کسی بھی تقریب کے لیے رنگ برنگا اور مزیدار اسٹارٹر ہے۔ کم کاربوہائیڈریٹ کے انتخاب کے لیے، اس سادہ بروشیٹا کو روایتی باگیٹ پر پیش کرنے کے بجائے مشروم میں بھر کر آزمائیں۔ یہ ترکیب The Diabetes Superfoods Cookbook and Meal Planner میں مل سکتی ہے۔","7","2 مشروم کیپس",
["1 پائنٹ گریپ ٹماٹر","2 چائے کے چمچ زیتون کا تیل","2 جوے لہسن","2 چائے کے چمچ خشک تلسی","1/3 کپ 2% موزاریلا پنیر (کدوکش کیا ہوا)","2 کھانے کے چمچ تازہ کدوکش کیا ہوا پارمیزان پنیر","14 اونس (تقریباً 14 مشروم) بڑے \"اسٹفر\" مشروم","1 کھانے کا چمچ بالسامک سرکہ"],
["اوون کو 350°F پر پہلے سے گرم کریں۔ ٹماٹروں کو چار ٹکڑوں میں کاٹ کر ایک طرف رکھ دیں۔","ایک فرائنگ پین میں زیتون کا تیل گرم کریں اور لہسن ڈالیں۔ لہسن کو تقریباً 1 منٹ سوتے کریں۔ ٹماٹر ڈالیں اور تقریباً 4 منٹ مزید سوتے کرتے رہیں۔ آنچ سے ہٹا لیں اور تلسی اور دونوں پنیر ہلا کر ملا دیں۔","مشروم کے ڈنٹھل نکال دیں اور انہیں ٹماٹر کے مرکب سے بھر دیں۔ اوون میں 15 منٹ بیک کریں۔","ذرا ٹھنڈا ہونے دیں، پھر بالسامک سرکہ ڈالیں۔ گرم پیش کریں۔"]))
recs.append(R(6498928,"گلوٹین فری چاکلیٹ کیلے کے مفنز","کوشش کریں کہ ایسا گلوٹین فری بیکنگ مکس استعمال کریں جس کے اجزاء میں پہلے نمبر پر براؤن رائس فلور ہو، تاکہ آپ کی سالم اناج کی مقدار بڑھ سکے۔","12","1 مفن",
["2 اسپرے، 0.5 گرام نان اسٹک کوکنگ اسپرے","1/4 کپ کینولا تیل","1/2 کپ 1:1 بیکنگ شوگر متبادل","1 چائے کا چمچ ونیلا ایکسٹریکٹ","2 درمیانے پکے کیلے (مسلے ہوئے)","2 بڑے انڈے","1 کپ آل پرپز گلوٹین فری بیکنگ مکس ((جیسے King Arthur بیکنگ مکس))","1/2 کپ گلوٹین فری، پرانے طرز کے رولڈ اوٹس","1/2 کپ کوکو پاؤڈر","1 کھانے کا چمچ پانی","2 کھانے کے چمچ چھوٹے چاکلیٹ چپس"],
["اوون کو 350 ڈگری F پر پہلے سے گرم کریں۔ مفن ٹنز میں مفن پیپرز لگائیں اور پیپرز پر کوکنگ اسپرے کریں۔","ایک بڑے پیالے میں تیل، شوگر متبادل اور ونیلا ملائیں۔ کیلے اور انڈے ایک ایک کر کے ڈالیں۔ اچھی طرح ملائیں۔","بیکنگ مکس، اوٹس، کوکو پاؤڈر اور پانی ہلا کر ملا دیں۔","آمیزے کو 12 مفن کپس میں چمچ سے ڈالیں۔ ہر مفن پر چھوٹے چاکلیٹ چپس ڈالیں (تمام مفنز پر برابر تقسیم کریں)۔","20-22 منٹ بیک کریں یا جب تک بیچ میں ڈالا گیا ٹوتھ پک صاف نہ نکلے۔","اوون سے نکالیں اور مفنز کو پین میں 10 منٹ ٹھنڈا ہونے دیں۔ مفنز کو پین سے نکالیں اور وائر ریک پر مکمل ٹھنڈا کریں۔"]))
recs.append(R(6499683,"مولی کے ٹوسٹ وہپڈ ریکوٹا اور چائیوز کے ساتھ","اگر آپ ایوکاڈو ٹوسٹ کے شوقین ہیں تو مولی کے اس ٹوسٹ سے کچھ نیا آزمائیں! ذیابیطس کے لیے موزوں اور پیٹ بھرنے والی یہ ترکیب ناشتے یا برنچ کے طور پر پیش کرنے کے لیے بہترین ہے۔","4","ٹوسٹ کا 1 سلائس",
["4 سلائس رائی کی ڈبل روٹی","2 عدد مولیاں (اوپر کے پتے ہٹائے ہوئے)","1/2 گڈی تازہ چائیوز","8 اونس ریکوٹا پنیر (کم چکنائی والا)"],
["ڈبل روٹی کو بروئلر کے نیچے یا ٹوسٹر میں ٹوسٹ کریں۔","ریکوٹا پنیر اور چائیوز (سجاوٹ کے لیے کچھ چائیوز بچا لیں) بلینڈر یا فوڈ پروسیسر میں ڈالیں اور ہموار ہونے تک پیوری بنا لیں۔ ایک طرف رکھ دیں۔","احتیاط سے (اگر آپ کے پاس مینڈولن ہو تو اس کی مدد سے) مولیوں کو ⅛ موٹے گول ٹکڑوں میں کاٹ لیں۔","پنیر اور چائیوز کا مرکب ڈبل روٹی کے 4 سلائسز میں تقسیم کریں اور برابر تہہ میں ہموار کر دیں۔","پنیر کے اوپر مولی کے قتلے اور کوئی بھی اضافی کٹے ہوئے چائیوز رکھیں۔ اگر چاہیں تو کالی مرچ چھڑکیں۔"]))
